/** Polls a condition until it evaluates to true. */
export async function eventually(condition: () => boolean | Promise<boolean>, timeout = 1000): Promise<void> {
  const start = Date.now();
  while (!(await condition())) {
    if (Date.now() - start > timeout) throw new Error('Condition not met within timeout');
    await new Promise(resolve => setTimeout(resolve, 10));
  }
}

