async function handleListSessions(
  ws: WebSocket,
  message: {limit?: number; before?: import('../../types/sessionStore.js').SessionCursor},
  session: ChatSession,
  sessionStore: SessionStore | undefined
) {
  const listFor = sessionStore?.listFor;
  if (!listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled or not implemented');
    return;
  }
  try {
    const summaries = await listFor.call(sessionStore, session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(s => ({
        ...s,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
      })),
    });
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, error.message);
      return;
    }
    const msg = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listFor failed', {userId: session.userId, error: msg});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

